<div class="style-check-page site-mobile-layout <?= c('style', 'page') ?>" id="top"><section class="<?= c('style', 'intro') ?>" aria-labelledby="style-page-title"><div class="<?= c('style', 'introTop') ?>"><div><?php breadcrumbs('Выбрать стиль'); ?><h1 id="style-page-title">Найдём стиль,<br class="<?= c('style', 'desktopBreak') ?>"> который вам подходит</h1></div><p><?= t('Выберите примеры, которые вам ближе по настроению и визуалу. По ответам я пойму, какие цвета, типографика, композиция и характер интерфейса лучше подойдут для будущего сайта.') ?></p></div>
<div class="<?= c('style', 'hints') ?>"><?php foreach ([['Оцените направление целиком', 'Сначала выберите общее впечатление: нравится, не нравится или пока сложно определиться.'], ['Отметьте, что именно понравилось', 'Выберите детали, которые вам близки: цвет, шрифты, композицию или графику.'], ['Не ищите готовый дизайн', 'Примеры нужны как ориентиры, чтобы точнее понять ваши визуальные предпочтения.']] as $index => [$title, $text]): ?><article><div><h2><?= h($title) ?></h2><span class="<?= c('style', 'marks') ?>" aria-hidden="true"><?php for ($mark = 0; $mark < 3; $mark++) image('/assets/figma/logo' . ($mark <= $index ? 2 : 3) . '.svg', '', ['width' => 20, 'height' => 20]); ?></span></div><p><?= t($text) ?></p></article><?php endforeach; ?></div></section>
<div id="style-quiz"><?php foreach ($site['styleChoice']['styles'] as $reference): ?><article class="shell"><h2><?= h($reference['title']) ?></h2><p><?= t($reference['description']) ?></p><?php if ($reference['images']) image($reference['images'][0], $reference['title'], ['style' => 'max-width:100%;height:auto', 'width' => 640]); ?></article><?php endforeach; ?><noscript><p class="php-nojs">Включите JavaScript, чтобы пройти тест и сохранить результат.</p></noscript></div></div>
